import{_ as t,a as r}from"./chunks/compare-tempsweep.B68yRgr8.js";import{_ as o,o as e,c as l,ai as i}from"./chunks/framework.C33Uq6m-.js";const b=JSON.parse('{"title":"对比","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/compare.md","filePath":"zh/guide/compare.md"}'),n={name:"zh/guide/compare.md"};function s(d,a,h,g,c,p){return e(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="对比" tabindex="-1">对比 <a class="header-anchor" href="#对比" aria-label="Permalink to &quot;对比&quot;">​</a></h1><p>对比页让你把同一个提示词同时发给多个模型或多组设置，并把结果并排比较。</p><p><strong>侧边栏位置：</strong> 对比 <strong>路由：</strong> <code>/compare</code></p><p><img src="'+t+'" alt="并排对比"></p><h2 id="界面概览" tabindex="-1">界面概览 <a class="header-anchor" href="#界面概览" aria-label="Permalink to &quot;界面概览&quot;">​</a></h2><p>页面顶部是提示词输入区，下方是一个可配置的<strong>槽位</strong>网格。每个槽位代表一种「模型 + 设置」的组合。</p><h2 id="配置槽位" tabindex="-1">配置槽位 <a class="header-anchor" href="#配置槽位" aria-label="Permalink to &quot;配置槽位&quot;">​</a></h2><ol><li>点击<strong>添加槽位</strong>创建一个对比槽位（最多 4 个）。</li><li>为每个槽位配置： <ul><li><strong>模型</strong> —— 从已安装的 Ollama 模型中选择（嵌入模型会被过滤掉）</li><li><strong>温度</strong> —— 控制随机性（0 = 确定性输出，越高越有创造性）</li><li><strong>系统提示词</strong> —— 可选的系统级指令</li><li><strong>采样参数</strong> —— Top-k、top-p、随机种子等 Ollama 选项</li></ul></li></ol><p>每个槽位会以标签形式显示自己的设置，便于快速查看。</p><h2 id="运行一次对比" tabindex="-1">运行一次对比 <a class="header-anchor" href="#运行一次对比" aria-label="Permalink to &quot;运行一次对比&quot;">​</a></h2><ol><li>在共享输入区输入你的提示词。</li><li>点击<strong>全部运行</strong>。所有槽位会同时流式输出。</li><li>实时观察结果并排出现。</li></ol><h2 id="视图" tabindex="-1">视图 <a class="header-anchor" href="#视图" aria-label="Permalink to &quot;视图&quot;">​</a></h2><h3 id="网格视图" tabindex="-1">网格视图 <a class="header-anchor" href="#网格视图" aria-label="Permalink to &quot;网格视图&quot;">​</a></h3><p>默认视图。所有槽位在网格布局中显示各自的流式结果。每个槽位显示：</p><ul><li>模型的回复</li><li>一个设置标签，显示模型名称与温度</li></ul><h3 id="差异视图" tabindex="-1">差异视图 <a class="header-anchor" href="#差异视图" aria-label="Permalink to &quot;差异视图&quot;">​</a></h3><p>切换到差异视图，可以看到两份输出之间<strong>按词高亮</strong>的变化。新增的文字标为绿色，删除的文字标为红色。</p><p><img src="'+r+'" alt="温度扫描对比"></p><h2 id="指标栏" tabindex="-1">指标栏 <a class="header-anchor" href="#指标栏" aria-label="Permalink to &quot;指标栏&quot;">​</a></h2><p>网格下方有一条可视化的<strong>指标栏</strong>，横向比较各槽位的关键性能指标：</p><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td><strong>TTFT</strong></td><td>首 token 时间 —— 每个模型开始回答的快慢</td></tr><tr><td><strong>Token/秒</strong></td><td>生成吞吐量</td></tr><tr><td><strong>总 token 数</strong></td><td>生成内容的 token 数量</td></tr></tbody></table><h2 id="快捷预设" tabindex="-1">快捷预设 <a class="header-anchor" href="#快捷预设" aria-label="Permalink to &quot;快捷预设&quot;">​</a></h2><p>一键配置常见的对比场景：</p><ul><li><strong>温度扫描</strong> —— 同一个模型在 3 个不同温度下（0.2、0.7、1.2）运行，观察创造性如何变化</li><li><strong>确定性配对</strong> —— 同一模型、同一种子、同一设置 —— 用于验证可复现性</li></ul><h2 id="保存、导出与分享" tabindex="-1">保存、导出与分享 <a class="header-anchor" href="#保存、导出与分享" aria-label="Permalink to &quot;保存、导出与分享&quot;">​</a></h2><p>对比结果会自动保存到 IndexedDB，你可以导出为 JSON 或 Markdown，也可以分享到 GitHub Discussions。这些功能在<a href="./language-compare.html#saving-results">语言对比</a>指南中有详细说明 —— 它们适用于所有类型的对比，不只是语言对比。</p><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li><strong>同一模型、不同设置</strong>往往比对比不同模型更有启发。试试改变温度或系统提示词。</li><li><strong>槽位会保留</strong> —— 在同一次会话中切换页面不会丢失配置。</li><li>迭代时使用<strong>较短的提示词</strong>，可以更快看到结果。</li></ul>',28)])])}const _=o(n,[["render",s]]);export{b as __pageData,_ as default};
